	 *   the above unified shutdown/poweroff sequence.
	 */
	intel_power_domains_driver_remove(display);
	enable_rpm_wakeref_asserts(&i915->runtime_pm);

	intel_runtime_pm_driver_last_release(&i915->runtime_pm);
}

